window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2beeb2432c726f13"]={"versions": [{"id": "FIG-2beeb2432c726f13", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition und Verwendung abstrakter Modellierungsstrukturen im AUTOSAR Generic Structure Template (GST). Das Diagramm veranschaulicht generische Metamodellierungsregeln für die Spezialisierung abstrakter und abgeleiteter Assoziationen bzw. Kompositionen durch Vererbung, Redefinition (<code>redefines</code>) und Teilmengenbildung (<code>subsets</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert vier Klassen sowie deren abstrakte und konkrete Beziehungen zueinander:</p>\n<ul class=\"fig-list\"><li><strong>Klassen:</strong>\n<ul class=\"fig-list\"><li><code>AbstractSuperClass</code> (kursiv, abstrakt): Abstrakte Basisklasse auf übergeordneter Ebene.\n</li><li><code>AbstractFeature</code> (kursiv, abstrakt): Abstraktes Ziel-Feature der Beziehungen von <code>AbstractSuperClass</code>.\n</li><li><code>ConcreteClass</code>: Konkrete Spezialisierung, die mittels Generalisierung (<code>--|&gt;</code>) von <code>AbstractSuperClass</code> erbt.\n</li><li><code>ConcreteFeature</code>: Konkrete Spezialisierung, die mittels Generalisierung (<code>--|&gt;</code>) von <code>AbstractFeature</code> erbt.\n</li></ul>\n</li><li><strong>Abstrakte Beziehungen (<code>AbstractSuperClass</code> nach <code>AbstractFeature</code>):</strong>\n<ul class=\"fig-list\"><li><code>+/atpReference</code>: Unidirektionale Assoziation, Multiplizität <code>1</code>, Stereotyp <code>«atpAbstract»</code>.\n</li><li><code>+/atpOtherReference</code>: Unidirektionale Assoziation, Multiplizität <code>1..*</code>, Eigenschaft <code>{union}</code>, Stereotypen <code>«atpAbstract,atpDerived»</code>.\n</li><li><code>+/atpFeature</code>: Komposition (schwarze Raute an <code>AbstractSuperClass</code>), Multiplizität <code>1</code>, Stereotyp <code>«atpAbstract»</code>.\n</li><li><code>+/atpUnionFeature</code>: Komposition (schwarze Raute an <code>AbstractSuperClass</code>), Multiplizität <code>0..*</code>, Eigenschaft <code>{union}</code>, Stereotypen <code>«atpAbstract,atpDerived»</code>.\n</li></ul>\n</li><li><strong>Konkrete Beziehungen (<code>ConcreteClass</code> nach <code>ConcreteFeature</code>):</strong>\n<ul class=\"fig-list\"><li><code>+myReference</code>: Unidirektionale Assoziation, deklariert <code>{redefines atpReference}</code>.\n</li><li><code>+myOtherReference</code>: Unidirektionale Assoziation, deklariert <code>{subsets atpOtherReference}</code>.\n</li><li><code>+myFurtherOtherReference</code>: Unidirektionale Assoziation, deklariert <code>{subsets atpOtherReference}</code>.\n</li><li><code>+myFeature</code>: Komposition, Multiplizität <code>1</code>, deklariert <code>{redefines atpFeature}</code>.\n</li><li><code>+myUnionFeatures</code>: Komposition, Multiplizität <code>0..*</code>, deklariert <code>{subsets atpUnionFeature}</code>.\n</li></ul>\n</li><li><strong>Notiz / Annotation:</strong>\n<ul class=\"fig-list\"><li>Ein Notizsymbol mit Text <code>corresponding ...</code> ist über gestrichelte Linien mit der abstrakten Referenz <code>+/atpReference</code> und der konkreten Referenz <code>+myReference</code> verknüpft.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodellierung; es stellt kein dynamisches Laufzeitverhalten und keine Sequenzabläufe dar.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm formalisiert die Modellierungsregeln des Generic Structure Template für AUTOSAR-Metamodell-Entwickler:</p>\n<ul class=\"fig-list\"><li>Beziehungen mit oberer Multiplizität <code>1</code> (<code>+/atpReference</code>, <code>+/atpFeature</code>) können ausschließlich redefiniert werden (<code>{redefines ...}</code>), eine Teilmengenbildung (<code>subsets</code>) ist unzulässig. Die redefinierende Beziehung ersetzt die abstrakte Beziehung vollständig.\n</li><li>Beziehungen mit oberer Multiplizität <code>&gt; 1</code> (<code>+/atpOtherReference</code>, <code>+/atpUnionFeature</code>), die als <code>{union}</code> markiert und als abgeleitet (<code>atpDerived</code>) gekennzeichnet sind, können ausschließlich spezialisiert werden, indem konkrete Relationen als Teilmengen (<code>{subsets ...}</code>) deklariert werden. Mehrere konkrete Rollen (z. B. <code>+myOtherReference</code> und <code>+myFurtherOtherReference</code>) können zur selben abstrakten Vereinigung beitragen.\n</li><li>Abstrakte Relationen tragen das Präfix <code>/</code> und das Stereotyp <code>«atpAbstract»</code> (bzw. <code>«atpAbstract,atpDerived»</code>).\n</li></ul>"}, {"id": "FIG-45f265bf7459b3e3", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition und Verwendung abstrakter Modellierungsstrukturen im AUTOSAR Generic Structure Template (GST). Das Diagramm veranschaulicht generische Metamodellierungsregeln für die Spezialisierung abstrakter und abgeleiteter Assoziationen bzw. Kompositionen durch Vererbung, Redefinition (<code>redefines</code>) und Teilmengenbildung (<code>subsets</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert vier Klassen sowie deren abstrakte und konkrete Beziehungen zueinander:</p>\n<ul class=\"fig-list\"><li><strong>Klassen:</strong>\n<ul class=\"fig-list\"><li><code>AbstractSuperClass</code> (kursiv, abstrakt): Abstrakte Basisklasse auf übergeordneter Ebene.\n</li><li><code>AbstractFeature</code> (kursiv, abstrakt): Abstraktes Ziel-Feature der Beziehungen von <code>AbstractSuperClass</code>.\n</li><li><code>ConcreteClass</code>: Konkrete Spezialisierung, die mittels Generalisierung (<code>--|&gt;</code>) von <code>AbstractSuperClass</code> erbt.\n</li><li><code>ConcreteFeature</code>: Konkrete Spezialisierung, die mittels Generalisierung (<code>--|&gt;</code>) von <code>AbstractFeature</code> erbt.\n</li></ul>\n</li><li><strong>Abstrakte Beziehungen (<code>AbstractSuperClass</code> nach <code>AbstractFeature</code>):</strong>\n<ul class=\"fig-list\"><li><code>+/atpReference</code>: Unidirektionale Assoziation, Multiplizität <code>1</code>, Stereotyp <code>«atpAbstract»</code>.\n</li><li><code>+/atpOtherReference</code>: Unidirektionale Assoziation, Multiplizität <code>1..*</code>, Eigenschaft <code>{union}</code>, Stereotypen <code>«atpAbstract,atpDerived»</code>.\n</li><li><code>+/atpFeature</code>: Komposition (schwarze Raute an <code>AbstractSuperClass</code>), Multiplizität <code>1</code>, Stereotyp <code>«atpAbstract»</code>.\n</li><li><code>+/atpUnionFeature</code>: Komposition (schwarze Raute an <code>AbstractSuperClass</code>), Multiplizität <code>0..*</code>, Eigenschaft <code>{union}</code>, Stereotypen <code>«atpAbstract,atpDerived»</code>.\n</li></ul>\n</li><li><strong>Konkrete Beziehungen (<code>ConcreteClass</code> nach <code>ConcreteFeature</code>):</strong>\n<ul class=\"fig-list\"><li><code>+myReference</code>: Unidirektionale Assoziation, deklariert <code>{redefines atpReference}</code>.\n</li><li><code>+myOtherReference</code>: Unidirektionale Assoziation, deklariert <code>{subsets atpOtherReference}</code>.\n</li><li><code>+myFurtherOtherReference</code>: Unidirektionale Assoziation, deklariert <code>{subsets atpOtherReference}</code>.\n</li><li><code>+myFeature</code>: Komposition, Multiplizität <code>1</code>, deklariert <code>{redefines atpFeature}</code>.\n</li><li><code>+myUnionFeatures</code>: Komposition, Multiplizität <code>0..*</code>, deklariert <code>{subsets atpUnionFeature}</code>.\n</li></ul>\n</li><li><strong>Notiz / Annotation:</strong>\n<ul class=\"fig-list\"><li>Ein Notizsymbol mit Text <code>corresponding ...</code> ist über gestrichelte Linien mit der abstrakten Referenz <code>+/atpReference</code> und der konkreten Referenz <code>+myReference</code> verknüpft.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodellierung; es stellt kein dynamisches Laufzeitverhalten und keine Sequenzabläufe dar.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm formalisiert die Modellierungsregeln des Generic Structure Template für AUTOSAR-Metamodell-Entwickler:</p>\n<ul class=\"fig-list\"><li>Beziehungen mit oberer Multiplizität <code>1</code> (<code>+/atpReference</code>, <code>+/atpFeature</code>) können ausschließlich redefiniert werden (<code>{redefines ...}</code>), eine Teilmengenbildung (<code>subsets</code>) ist unzulässig. Die redefinierende Beziehung ersetzt die abstrakte Beziehung vollständig.\n</li><li>Beziehungen mit oberer Multiplizität <code>&gt; 1</code> (<code>+/atpOtherReference</code>, <code>+/atpUnionFeature</code>), die als <code>{union}</code> markiert und als abgeleitet (<code>atpDerived</code>) gekennzeichnet sind, können ausschließlich spezialisiert werden, indem konkrete Relationen als Teilmengen (<code>{subsets ...}</code>) deklariert werden. Mehrere konkrete Rollen (z. B. <code>+myOtherReference</code> und <code>+myFurtherOtherReference</code>) können zur selben abstrakten Vereinigung beitragen.\n</li><li>Abstrakte Relationen tragen das Präfix <code>/</code> und das Stereotyp <code>«atpAbstract»</code> (bzw. <code>«atpAbstract,atpDerived»</code>).\n</li></ul>"}], "trans": [{"from": "FIG-2beeb2432c726f13", "to": "FIG-45f265bf7459b3e3", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
